function actions(){const c=copy();return `<div class="staff-modal-actions"><button class="outline" type="button" data-staff-cancel>${c.cancel}</button><button class="outline" type="button" data-staff-close>${c.close}</button><button class="primary" type="submit">${c.save}</button></div>`}
function wipeSecrets(form){form?.querySelectorAll('input[type="password"]').forEach(input=>{input.value='';input.removeAttribute('value')})}
function permitted(row,key){return typeof row?.card_version==='string'&&row.card_version.length>0&&Array.isArray(row.editable_fields)&&row.editable_fields.includes(key)}
function reason(row,key){const w=employeeWords(),code=row?.read_only_reasons?.[key];if(['first_name','last_name','login','email','phone','avatar_url'].includes(key))return w.shared;if(key==='account_status')return w.accountReason;return !row?.card_version?w.outdated:({self_membership_protected:w.selfProtected,self_deactivation_forbidden:w.selfProtected,owner_protected:w.ownerProtected,protected_member:w.protectedMember,permission_scope:w.permissionScope,member_inactive:w.inactiveMember}[code]||w.restricted)}
function fieldError(key){return `<small data-field-error="${esc(key)}" id="staffFieldError-${esc(key)}" role="alert"></small>`}
function field(key,label,value='',attributes='',help=''){return `<label>${esc(label)}<input name="${key}" value="${esc(value)}" ${attributes} aria-describedby="staffFieldHelp-${key} staffFieldError-${key}"><small id="staffFieldHelp-${key}" class="sub">${esc(help)}</small>${fieldError(key)}</label>`}
const profileKeys=['first_name','last_name','login','phone','avatar_url'];
function profileAllowed(row){return profile?.role==='owner'&&profile.active===true&&row?.active===true&&row.profile_assign_available===true&&typeof row.card_version==='string'&&!!row.card_version}
function accountFields(row){const w=employeeWords(),c=copy(),creating=!row,editable=creating||profileAllowed(row);return `<section class="staff-section"><h3>${w.identity}</h3><div class="grid">`+
field('first_name',w.first,row?.first_name||'',editable?'required maxlength="120" autocomplete="given-name"':'readonly',editable?'':reason(row,'first_name'))+
field('last_name',w.last,row?.last_name||'',editable?(creating?'required minlength="2" ':'')+'maxlength="120" autocomplete="family-name"':'readonly',editable?'':reason(row,'last_name'))+
field('login',w.login,row?.login||'',editable?'required minlength="3" maxlength="64" pattern="[A-Za-z0-9_.-]{3,64}" autocomplete="username"':'readonly',editable?'':reason(row,'login'))+
field('email',c.email,row?.email||'',creating?'type="email" autocomplete="email"':'readonly',creating?'':reason(row,'email'))+
field('phone',w.phone,row?.phone||'',editable?'maxlength="40" autocomplete="tel"':'readonly',(editable?'':reason(row,'phone')+' ')+w.phoneHelp)+
field('avatar_url',w.avatar,row?.avatar_url||'',profileAllowed(row)?'type="url" maxlength="500"':'readonly',profileAllowed(row)?'':creating?w.shared:reason(row,'avatar_url'))+
field('account_status',w.account,row?accountStatus(row.account_status):w.createdStatus,'readonly',w.accountReason)+`</div></section>`}
function accountStatus(value){const w=employeeWords();return value==='active'?w.active:['disabled','inactive'].includes(value)?w.inactive:value?String(value):w.unknownStatus}
function roleOptions(role,c){const w=employeeWords(),worker={ru:'Исполнитель',az:'İcraçı',en:'Worker'}[window.tenantI18n?.language]||'Worker',labels={owner:w.owner,admin:w.admin,operator:c.operator,worker,manager:c.manager,master:w.master},visible=[['worker',worker],['operator',c.operator],['manager',c.manager],['master',w.master]];if(profile?.role==='owner')visible.push(['admin',w.admin]);if(role&&!visible.some(([key])=>key===role))visible.unshift([role,labels[role]||w.legacyRole+': '+role]);return visible.map(([key,label])=>`<option value="${esc(key)}" ${role===key?'selected':''}>${esc(label)}</option>`).join('')}
function permissionControls(selected,legacy=[],disabled=false,partials=false,catalog=rightsCatalog()){const w=employeeWords(),a=accessWords();return catalog.map(([key,label,help])=>{const partial=partials&&!selected.includes(key)&&selected.some(value=>value.startsWith(key+':'));return `<fieldset class="staff-permission-card staff-section-permission" data-permission-card="${esc(key)}"><legend>${esc(label)}</legend><div class="staff-permission-options"><label class="staff-right"><input type="checkbox" data-permission value="${esc(key)}" ${disabled?'disabled':''} aria-describedby="staffSectionHelp-${esc(key)}" ${selected.includes(key)||partial?'checked':''} ${partial?'data-permission-partial="true"':''}>${esc(help)}</label></div><p class="sub" id="staffSectionHelp-${esc(key)}">${esc(a.coarseHelp)}${partial?' '+esc(a.partial):''}</p></fieldset>`}).join('')+(legacy.length?`<p class="staff-legacy"><b>${w.legacy}</b><br>${esc(legacy.join(', '))}</p>`:'')+fieldError('permissions')}
