async function assignAccount(form,row,kind){const current=formOperation(form);if(!current()||!(kind==='profile'?profileAllowed(row):assignAllowed(row))||form.dataset.assignPending==='true'||form.dataset.blocked==='true'||form.dataset.applied==='true')return false;const w=employeeWords(),data=new FormData(form),command={action:'assign_member_'+kind,...writeIdentity(),telegram_id:row.telegram_id,expected_version:row.card_version};clearErrors(form);if(kind==='password'){command.password=String(data.get('password')||'');command.confirm_password=String(data.get('confirm_password')||'');if(command.password!==command.confirm_password){form.querySelector('[data-field-error=confirm_password]').textContent=w.mismatch;return false}if(command.password.length<12||command.password.length>256){form.querySelector('[data-field-error=password]').textContent=w.invalid;return false}}else if(kind==='email'){const input=form.elements.namedItem('new_email');if(!input.value.trim()||!input.checkValidity()){form.querySelector('[data-field-error=new_email]').textContent=w.invalid;return false}command.email=input.value.trim()}else{command.changes=profileChanges(form,row);if(!Object.keys(command.changes).length)return true;for(const key of Object.keys(command.changes)){const input=form.elements.namedItem(key);if(!input.checkValidity()){form.querySelector('[data-field-error="'+key+'"]').textContent=w.invalid;return false}}}
form.dataset.assignPending='true';pendingWrites.set(form,{row,pane:'profile'});const buttons=[...form.querySelectorAll('button[type=button],button[type=submit]')],disabled=buttons.map(b=>b.disabled);buttons.forEach(b=>b.disabled=true);try{const result=await api('/api/platform/members',{method:'POST',body:JSON.stringify(command)});if(!current())return false;if(!receiptValid(result,row,false)||result.applied[kind+'_changed']!==true){form.dataset.blocked='true';form.querySelector('#staffSaveError').textContent=w.unknown;reviewButton(form,row,'profile');return false}if(kind!=='profile')wipeSecrets(form);row.card_version=result.applied.card_version;if(kind==='email'){row.email=command.email;const oldEmail=form.elements.namedItem('email');if(oldEmail)oldEmail.value=command.email}else if(kind==='profile'){const saved=result.applied.profile||command.changes;for(const key of profileKeys)if(Object.prototype.hasOwnProperty.call(saved,key)){const input=form.elements.namedItem(key),unchanged=input.value===String(data.get(key)||'');row[key]=saved[key];if(unchanged)input.value=saved[key]||''}}saveNotice=w.saved;form.querySelector('#staffSaveError').textContent=w.saved;renderContent();dirty=hasPendingChanges(form,row);return true}catch(error){if(!current())return false;if([400,403,404,409].includes(error.status))showError(form,error,row,'profile');else{form.dataset.blocked='true';form.querySelector('#staffSaveError').textContent=w.unknown;reviewButton(form,row,'profile')}return false}finally{pendingWrites.delete(form);if(kind!=='profile')wipeSecrets(form);if(current()){form.dataset.assignPending='false';if(form.dataset.blocked!=='true'&&form.dataset.applied!=='true')buttons.forEach((b,i)=>b.disabled=disabled[i])}}}

